using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns the text shown on a bot's profile page and sent together with the link when users share the bot in the given language. Can be called only if userTypeBot.can_be_edited == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> GetBotInfoShortDescriptionAsync(long botUserId = default, string languageCode = default)
    {

           using var activity =  StartCallActivity("GetBotInfoShortDescriptionAsync", typeof(GetBotInfoShortDescription).FullName ?? "GetBotInfoShortDescriptionAsync");

           try
           {
             return client.GetBotInfoShortDescriptionAsync(botUserId, languageCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
